import java.util.List;

abstract class Enemy {
    private final String name;
    protected Enemy(String name) { this.name = name; }
    public String getName() { return name; }
    public abstract int attack();
    public abstract int reward();
}

class Slime extends Enemy {
    Slime() { super("Slime"); }
    @Override public int attack() { return 3; }
    @Override public int reward() { return 5; }
}

class Archer extends Enemy {
    Archer() { super("Archer"); }
    @Override public int attack() { return 7; }
    @Override public int reward() { return 12; }
}

class Boss extends Enemy {
    private final int level;
    Boss(int level) {
        super("Boss L" + level);
        this.level = level;
    }
    @Override public int attack() { return 20 * level; }
    @Override public int reward() { return 100 * level; }
}

public class Wave {
    public static int totalAttack(List<Enemy> wave) {
        int total = 0;
        for (Enemy e : wave) total += e.attack();   // each enemy's own attack()
        return total;
    }

    public static int totalReward(List<Enemy> wave) {
        int total = 0;
        for (Enemy e : wave) total += e.reward();
        return total;
    }

    public static String mostDangerous(List<Enemy> wave) {
        if (wave.isEmpty()) return "none";
        Enemy best = wave.get(0);
        for (Enemy e : wave) if (e.attack() > best.attack()) best = e;
        return best.getName();
    }
}

