import java.util.List;

class Potion {
    final int heal;
    Potion(int heal) { this.heal = heal; }
}

class Weapon {
    final String name;
    final int damage;
    Weapon(String name, int damage) { this.name = name; this.damage = damage; }
}

class Coin {
    final int value;
    Coin(int value) { this.value = value; }
}

public class Items {
    public static String describe(Object item) {
        if (item instanceof Potion p) return "Potion +" + p.heal + " hp";
        if (item instanceof Weapon w) return w.name + " " + w.damage + " dmg";
        if (item instanceof Coin c) return "Coin x" + c.value;
        return "Unknown";   // also null: instanceof is false for null
    }

    public static int totalCoins(List<Object> loot) {
        int total = 0;
        for (Object o : loot) if (o instanceof Coin c) total += c.value;
        return total;
    }

    public static int bestDamage(List<Object> loot) {
        int best = 0;
        for (Object o : loot) if (o instanceof Weapon w && w.damage > best) best = w.damage;
        return best;
    }
}

