import java.util.List;

abstract class Worker {
    private final String name;
    protected Worker(String name) { this.name = name; }
    public String getName() { return name; }
    public abstract double weeklyPay();
    public String payslip() { return name + ": " + weeklyPay() + " KSh"; }
}

class Doctor extends Worker {
    private final double salary;
    Doctor(String name, double salary) { super(name); this.salary = salary; }
    @Override public double weeklyPay() { return salary; }
}

class Nurse extends Worker {
    private final int hours;
    private final double rate;
    Nurse(String name, int hours, double rate) {
        super(name);
        this.hours = hours;
        this.rate = rate;
    }
    @Override public double weeklyPay() {
        int normal = Math.min(hours, 40);
        int extra = Math.max(0, hours - 40);
        return normal * rate + extra * rate * 1.5;
    }
}

class Volunteer extends Worker {
    Volunteer(String name) { super(name); }
    @Override public double weeklyPay() { return 500.0; }
}

public class Payroll {
    public static double total(List<Worker> staff) {
        double sum = 0;
        for (Worker w : staff) sum += w.weeklyPay();   // each kind pays its own way
        return sum;
    }

    public static String highestPaid(List<Worker> staff) {
        if (staff.isEmpty()) return "none";
        Worker best = staff.get(0);
        for (Worker w : staff) if (w.weeklyPay() > best.weeklyPay()) best = w;
        return best.getName();
    }
}
